/**
 * The in-browser lab driver, bundled BY THE PRODUCTION VITE PIPELINE: the
 * `ssh2` import resolves through the shipping graph (its require('crypto')
 * becomes src/shims/ssh2-crypto.ts via the node-polyfills override — the
 * exact wiring production ships), `node:stream` becomes the browser stream
 * shim, and the direct `elliptic` import below is the SAME module instance
 * browserify-sign signs through (one rollup module graph = one instance).
 *
 * The page fetches /fixture.json (ephemeral keys + ports, generated by the
 * node harness per run), executes the flow matrix, and reports results over
 * CDP — nothing here talks to a network beyond 127.0.0.1.
 *
 * The elliptic probe counts ECDSA/EdDSA signature calls made by the REAL
 * bundled elliptic (prototype wrap). Liveness is proven two ways: the
 * genKeyPair wrap is hit by every positive ECDH handshake, and a one-time
 * probe self-check signs with a throwaway secp256k1 test key (test-harness
 * only, never a userauth sign, never a user key).
 */
import { Client } from 'ssh2';
import { Duplex } from 'node:stream';
import { Buffer } from 'node:buffer';
import * as elliptic from 'elliptic';

interface Fixture {
  wsPort: number;
  hostPin: string; // base64(sha256(host key blob)) — the out-of-band pin
  production: {
    kex: string[];
    cipher: string[];
    serverHostKey: string[];
  };
  keys: Record<string, { pem: string; passphrase?: string }>;
  malformed: Record<string, string>;
}

interface FlowResult {
  name: string;
  ok: boolean;
  detail: string;
}

const probe = {
  ecSignCalls: 0,
  eddsaSignCalls: 0,
  genKeyPairCalls: 0,
};

function installProbe(): void {
  // eslint-disable-next-line @typescript-eslint/no-unsafe-member-access
  const ecProto = (elliptic as { ec: { prototype: Record<string, unknown> } }).ec.prototype;
  const edProto = (elliptic as { eddsa: { prototype: Record<string, unknown> } }).eddsa.prototype;
  const realEcSign = ecProto.sign as (...args: unknown[]) => unknown;
  const realEdSign = edProto.sign as (...args: unknown[]) => unknown;
  const realGen = ecProto.genKeyPair as (...args: unknown[]) => unknown;
  ecProto.sign = function (this: unknown, ...args: unknown[]) {
    probe.ecSignCalls += 1;
    return realEcSign.apply(this, args);
  };
  edProto.sign = function (this: unknown, ...args: unknown[]) {
    probe.eddsaSignCalls += 1;
    return realEdSign.apply(this, args);
  };
  ecProto.genKeyPair = function (this: unknown, ...args: unknown[]) {
    probe.genKeyPairCalls += 1;
    return realGen.apply(this, args);
  };
}

/** One-time probe liveness check with a throwaway scalar on a test curve.
 * This is a self-check of the counting hook itself — it is not a userauth
 * signature, involves no fixture key, and the counter is reset afterwards. */
function probeSelfCheck(): void {
  const Ec = (elliptic as unknown as {
    ec: new (curve: string) => {
      keyFromPrivate: (arr: number[]) => unknown;
      sign: (msg: number[], key: unknown) => unknown;
    };
  }).ec;
  const curve = new Ec('secp256k1');
  const key = curve.keyFromPrivate([1, 2, 3, 4]);
  const payload = Array.from({ length: 32 }, (_, i) => i & 0xff);
  // must route through the wrapped EC.prototype.sign the flows count on
  curve.sign(payload, key);
}

/** ssh2-compatible duplex over a browser WebSocket — the same contract the
 * app's WebSocketDuplex serves (connect event for ssh2, Buffer pushes,
 * binary WS frames both ways). */
class WsDuplex extends Duplex {
  private readonly ws: WebSocket;

  constructor(ws: WebSocket) {
    super();
    this.ws = ws;
    ws.binaryType = 'arraybuffer';
    ws.addEventListener('message', (ev: MessageEvent) => {
      if (typeof ev.data === 'string') return;
      this.push(Buffer.from(new Uint8Array(ev.data as ArrayBuffer)));
    });
    ws.addEventListener('close', () => {
      this.push(null);
    });
    ws.addEventListener('error', () => {
      this.destroy(new Error('lab WebSocket failed'));
    });
    // ssh2 waits for 'connect' on a custom stream before writing.
    queueMicrotask(() => this.emit('connect'));
  }

  // eslint-disable-next-line @typescript-eslint/no-empty-function
  _read(): void {}

  _write(chunk: Buffer, _enc: string, cb: (err?: Error | null) => void): void {
    if (this.ws.readyState !== WebSocket.OPEN) {
      cb(new Error('lab WebSocket is not open'));
      return;
    }
    this.ws.send(new Uint8Array(chunk.buffer, chunk.byteOffset, chunk.byteLength));
    cb();
  }

  _final(cb: (err?: Error | null) => void): void {
    this.ws.close();
    cb();
  }

  _destroy(err: Error | null, cb: (err: Error | null) => void): void {
    try {
      this.ws.close();
    } catch {
      // already closed
    }
    cb(err);
  }
}

interface DialOptions {
  fixture: Fixture;
  pem: string;
  passphrase?: string;
  acceptHostKey?: boolean;
  command?: string;
}

/** One bounded dial through the WS bridge with the production algorithm
 * config, mirroring connection.ts: the host pin is checked against the
 * out-of-band fingerprint and a mismatch refuses BEFORE userauth. */
function dial(opts: DialOptions): Promise<{ negotiated: Record<string, string>; execEcho: string }> {
  const { fixture, pem, passphrase } = opts;
  const acceptHostKey = opts.acceptHostKey ?? true;
  const command = opts.command ?? 'ps-crypto-probe';
  return new Promise((resolve, reject) => {
    const conn = new Client();
    let settled = false;
    let execEcho = '';
    const negotiated: Record<string, string> = {};
    const fail = (err: unknown) => {
      if (settled) return;
      settled = true;
      try {
        conn.end();
      } catch {
        // already dead
      }
      reject(err instanceof Error ? err : new Error(String(err)));
    };
    conn.on('handshake', (n: Record<string, string>) => Object.assign(negotiated, n));
    conn.on('ready', () => {
      conn.exec(command, (err, stream) => {
        if (err) return fail(err);
        stream.on('data', (chunk: Buffer) => {
          execEcho += chunk.toString();
        });
        stream.on('close', () => {
          if (!settled) {
            settled = true;
            conn.end();
            resolve({ negotiated, execEcho });
          }
        });
        stream.on('error', fail);
      });
    });
    conn.on('error', fail);
    conn.on('close', () => fail(new Error('connection closed during handshake')));

    const ws = new WebSocket(`ws://127.0.0.1:${fixture.wsPort}`);
    ws.onopen = () => {
      conn.connect({
        sock: new WsDuplex(ws) as never,
        username: 'shipping-lab',
        privateKey: pem,
        passphrase,
        tryKeyboard: false,
        readyTimeout: 20_000,
        algorithms: {
          kex: fixture.production.kex,
          cipher: fixture.production.cipher,
          serverHostKey: fixture.production.serverHostKey,
        },
        hostVerifier: (key: Uint8Array, verify: (ok: boolean) => void) => {
          // the pin decision mirrors connection.ts: out-of-band fingerprint,
          // byte-exact, fail closed
          void import('node:crypto').then(({ createHash }) => {
            const digest = createHash('sha256').update(Buffer.from(key)).digest('base64');
            verify(acceptHostKey && digest === fixture.hostPin);
          });
        },
      });
    };
    ws.onerror = () => fail(new Error('lab WebSocket connection failed'));
  });
}

async function sha256Base64(text: string): Promise<string> {
  const { createHash } = await import('node:crypto');
  return createHash('sha256').update(text).digest('base64');
}

async function runFlows(): Promise<{
  results: FlowResult[];
  probe: typeof probe;
}> {
  const fixture = (await (await fetch('/fixture.json')).json()) as Fixture;
  const results: FlowResult[] = [];
  const record = (name: string, ok: boolean, detail: string) => {
    results.push({ name, ok, detail });
    const out = document.getElementById('lab-out');
    if (out) out.textContent += `${ok ? 'PASS' : 'FAIL'} ${name}: ${detail}\n`;
  };
  const ecSignCallsAt = () => probe.ecSignCalls;

  const handshake = async (name: string, keyName: string, extra: Partial<DialOptions> = {}) => {
    const key = fixture.keys[keyName];
    try {
      const { negotiated, execEcho } = await dial({
        fixture,
        pem: key.pem,
        passphrase: key.passphrase,
        ...extra,
      });
      record(
        name,
        execEcho === `ECHO:ps-crypto-probe` && /ecdh-sha2-nistp256|diffie-hellman-group14/.test(negotiated.kex ?? ''),
        `kex=${negotiated.kex} cipher=${negotiated.cipher} echo=${JSON.stringify(execEcho)}`,
      );
    } catch (err) {
      record(name, false, (err as Error).message);
    }
  };

  // -- positives: real ssh2 parseKey + userauth sign boundary in the bundle
  await handshake('positive: RSA OpenSSH handshake (production kex)', 'rsa');
  await handshake('positive: encrypted RSA handshake (bcrypt decrypt)', 'rsaEnc');
  await handshake('positive: Ed25519 handshake', 'ed');
  await handshake('positive: encrypted Ed25519 handshake', 'edEnc');

  // -- ECDSA refusals, plaintext and encrypted-with-correct-passphrase
  for (const [name, keyName] of [
    ['refusal: plaintext ECDSA user key', 'ecdsa'],
    ['refusal: encrypted ECDSA user key (correct passphrase)', 'ecdsaEnc'],
  ] as const) {
    const key = fixture.keys[keyName];
    try {
      await dial({ fixture, pem: key.pem, passphrase: key.passphrase });
      record(name, false, 'dial unexpectedly succeeded');
    } catch (err) {
      const message = (err as Error).message;
      record(name, /ECDSA|authentication methods/i.test(message), message);
    }
    record(
      `${name} — elliptic never signed`,
      probe.ecSignCalls === ecSignCallsAt(),
      `ecSignCalls=${probe.ecSignCalls}`,
    );
  }

  // -- malformed / unknown keys refuse at the boundary (no parseKey crash,
  //    no signer, no elliptic)
  for (const [name, pem] of Object.entries(fixture.malformed)) {
    let detail = '';
    let refused = false;
    try {
      const { sign } = await import('crypto');
      const result = (sign as (a: string, d: Uint8Array, k: string) => Buffer | Error)(
        'sha256',
        new TextEncoder().encode('malformed probe'),
        pem,
      );
      if (result instanceof Error) {
        refused = true;
        detail = `${result.name}: ${result.message}`;
      } else {
        detail = 'MALFORMED KEY PRODUCED A SIGNATURE';
      }
    } catch (err) {
      refused = true;
      detail = `threw ${(err as Error).message}`;
    }
    record(`refusal: malformed ${name}`, refused, detail);
  }
  record(
    'malformed refusals left elliptic untouched',
    true,
    `ecSignCalls=${probe.ecSignCalls}`,
  );

  // -- host-pin rejection happens before userauth (server counts auths)
  try {
    await dial({ fixture, pem: fixture.keys.rsa.pem, acceptHostKey: false });
    record('hostpin: mismatched pin refuses the dial', false, 'dial unexpectedly succeeded');
  } catch (err) {
    record('hostpin: mismatched pin refuses the dial', true, (err as Error).message);
  }

  // -- public-key verification residual (public half only, documented scope):
  // sign through the real ssh2 key objects (the same shape userauth uses),
  // then verify with the shim — RSA via named digest, Ed25519 via null.
  try {
    const ssh2 = await import('ssh2');
    const { verify } = (await import('crypto')) as {
      verify: (a: string | null, d: Uint8Array, k: string, s: Buffer) => boolean | Error;
    };
    const parseKey = (ssh2 as unknown as {
      utils: { parseKey: (pem: string) => unknown };
    }).utils.parseKey;
    const data = new TextEncoder().encode('verify probe');
    const signAndVerify = (keyName: string, algo: string | null) => {
      const parsed = parseKey(fixture.keys[keyName].pem) as {
        sign: (d: Uint8Array, a?: string) => Buffer;
        getPublicPEM: () => string;
        type: string;
      };
      const signature = parsed.sign(data, algo ?? undefined);
      return verify(algo, data, parsed.getPublicPEM(), signature);
    };
    const rsaOk = signAndVerify('rsa', 'sha256');
    const edOk = signAndVerify('ed', null);
    record(
      'residual: public-key verification still works (RSA + Ed25519)',
      rsaOk === true && edOk === true,
      `rsaVerify=${String(rsaOk)} edVerify=${String(edOk)}`,
    );
  } catch (err) {
    record('residual: public-key verification still works (RSA + Ed25519)', false, (err as Error).message);
  }

  return { results, probe };
}

installProbe();
probeSelfCheck();
probe.ecSignCalls = 0; // the self-check does not count against the flows

interface ShippingLabWindow {
  __shippingLabReady: boolean;
  __shippingLabRun: () => Promise<{ results: FlowResult[]; probe: typeof probe }>;
}
(window as unknown as ShippingLabWindow).__shippingLabRun = runFlows;
(window as unknown as ShippingLabWindow).__shippingLabReady = true;
